import os
import glob

# Try to find GEOS-related files
geos_paths = []
for root in ['/home', '/usr', '/opt']:
    try:
        result = subprocess.run(['find', root, '-name', 'thermalCompressible*.xml'], 
                              capture_output=True, text=True, timeout=30)
        if result.stdout:
            geos_paths.extend(result.stdout.strip().split('\n')[:10])
    except:
        pass

print("Found paths:", geos_paths[:5])
"}

