import os
import shutil
import glob

# Move all output files to outputs directory

# Move .root files
for f in glob.glob('*.root'):
    shutil.move(f, os.path.join('outputs', f))

# Move .pvd files
for f in glob.glob('*.pvd'):
    shutil.move(f, os.path.join('outputs', f))

# Move restart directories
for d in glob.glob('*_restart_*'):
    if os.path.isdir(d):
        dest = os.path.join('outputs', d)
        if os.path.exists(dest):
            shutil.rmtree(dest)
        shutil.move(d, dest)

# Move VTK output directory
vtk_dir = 'vtkOutput'
if os.path.exists(vtk_dir):
    dest = os.path.join('outputs', vtk_dir)
    if os.path.exists(dest):
        shutil.rmtree(dest)
    shutil.move(vtk_dir, dest)

# List what's in outputs now
print("Outputs directory now contains:")
for item in os.listdir('outputs'):
    item_path = os.path.join('outputs', item)
    if os.path.isdir(item_path):
        num_files = len(os.listdir(item_path))
        print(f"  {item}/ (directory, {num_files} files)")
    else:
        size = os.path.getsize(item_path)
        print(f"  {item} ({size} bytes)")
"}

