import os

# Check VTK output files
vtk_dir = 'outputs/vtkOutput'
if os.path.exists(vtk_dir):
    vtk_files = sorted([f for f in os.listdir(vtk_dir) if f.endswith('.vtu')])
    print(f"Found {len(vtk_files)} VTK output files:")
    for f in vtk_files[:5]:
        size = os.path.getsize(os.path.join(vtk_dir, f))
        print(f"  {f} ({size} bytes)")
    if len(vtk_files) > 5:
        print(f"  ... and {len(vtk_files)-5} more files")
